		if s.key.sameSection(key) {
			text := line
			if s.entryEnd > 0 && f.data[s.entryEnd-1] != '\n' {
				// The section is the last line and lacks a terminator.
				text = "\n" + text
			}

			return f.apply([]edit{{start: s.entryEnd, end: s.entryEnd, text: text}})
		}
