					break
				}
			}

			if !deleted && !isSpace(data[i]) {
				return true
			}
		}
	}

	return false
}

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\r' || c == '\n'
}

func (f *File) rewrite(o *optionRec, key Key, value string) error {
	return f.apply([]edit{f.writeEdit(o, key, value)})
