	if !errors.Is(err, config.ErrMultipleValues) {
		t.Fatalf("Set on a multivalued key = %v, want ErrMultipleValues", err)
	}

	if got := string(f.Bytes()); got != "[foo]\n\tbar = one\n\tbar = two\n" {
