	if err := f.ReplaceAll(mustKey(t, "foo.bar"), "three"); err != nil {
		t.Fatalf("ReplaceAll: %v", err)
	}

	if got, want := string(f.Bytes()), "[foo]\n\tbar = three\n"; got != want {
