package config

import "strings"

// parser walks a configuration file byte by byte, recording the position of
// every section header and variable so they can later be spliced in place.
type parser struct {
	data []byte
	pos  int
	line int

	f      *File
	curSec *sectionRec
}

func (p *parser) run() error {
	defer func() {
		if n := len(p.f.sections); n > 0 {
			p.f.sections[n-1].regionEnd = len(p.data)
		}
	}()

	for p.pos < len(p.data) {
		lineStart := p.pos
		p.skipBlank()

		if p.atLineEnd() {
			p.consumeLineEnd()

			continue
		}

		if p.data[p.pos] == '#' || p.data[p.pos] == ';' {
			p.skipToLineEnd()
			p.consumeLineEnd()

			continue
		}

		sawHeader := false

		if p.data[p.pos] == '[' {
			if err := p.parseHeader(lineStart); err != nil {
				return err
			}

			sawHeader = true

			p.skipBlank()

			if p.atLineEnd() || p.data[p.pos] == '#' || p.data[p.pos] == ';' {
				p.curSec.plain = p.atLineEnd()
				p.skipToLineEnd()
				p.consumeLineEnd()
				p.curSec.lineEnd = p.pos
				p.curSec.entryEnd = p.pos

				continue
			}
			// Git allows a variable to follow the header on the same line.
		}

		if err := p.parseVariable(lineStart, !sawHeader); err != nil {
			return err
		}
	}

	return nil
}

func (p *parser) parseHeader(lineStart int) error {
	p.pos++ // consume '['

	start := p.pos
	for p.pos < len(p.data) && (isAlnum(p.data[p.pos]) || p.data[p.pos] == '-' || p.data[p.pos] == '.') {
		p.pos++
	}

	name := string(p.data[start:p.pos])
	if name == "" {
		return p.err()
	}

	var key Key

	p.skipBlank()

	switch {
	case p.pos < len(p.data) && p.data[p.pos] == '"':
		sub, err := p.parseSubsection()
		if err != nil {
			return err
		}

		if !validSectionName(name) {
			return p.err()
		}

		key = Key{Section: name, Subsection: sub, HasSubsection: true}
	case strings.Contains(name, "."):
		// Deprecated "[section.subsection]" form. Git lower-cases the whole
		// header, so the subsection is case-insensitive here only.
		sec, sub, _ := strings.Cut(name, ".")
		if !validSectionName(sec) {
			return p.err()
		}

		key = Key{
			Section: sec,
			// Git folds the whole "[section.subsection]" header, so only in
			// this deprecated form is the subsection case-insensitive.
			Subsection:    strings.ToLower(sub),
			HasSubsection: true,
		}
	default:
		if !validSectionName(name) {
			return p.err()
		}

		key = Key{Section: name}
	}

	p.skipBlank()

	if p.pos >= len(p.data) || p.data[p.pos] != ']' {
		return p.err()
	}

	p.pos++

	sec := &sectionRec{key: key, lineStart: lineStart, headerEnd: p.pos}
	if n := len(p.f.sections); n > 0 {
		// A section occurrence owns the file up to the next header.
		p.f.sections[n-1].regionEnd = lineStart
	}

	p.f.sections = append(p.f.sections, sec)
	p.curSec = sec

	return nil
}

func (p *parser) parseSubsection() (string, error) {
	p.pos++ // consume '"'

	var b strings.Builder

	for {
		if p.pos >= len(p.data) || p.data[p.pos] == '\n' {
			return "", p.err()
		}

		c := p.data[p.pos]
		if c == 0 {
			return "", p.err()
		}

		if c == '"' {
			p.pos++

			return b.String(), nil
		}

		if c == '\\' {
			p.pos++

			if p.pos >= len(p.data) || p.data[p.pos] == '\n' {
				return "", p.err()
			}

			b.WriteByte(p.data[p.pos])
			p.pos++

			continue
		}

		b.WriteByte(c)

		p.pos++
	}
}

func (p *parser) parseVariable(lineStart int, alone bool) error {
	if p.curSec == nil {
		// A variable before any section header has no key Git could name.
		return p.err()
	}

	nameStart := p.pos
	for p.pos < len(p.data) && (isAlnum(p.data[p.pos]) || p.data[p.pos] == '-') {
		p.pos++
	}

	name := string(p.data[nameStart:p.pos])
	if !validVariableName(name) {
		return p.err()
	}

	o := &optionRec{
		key: Key{
			Section:       p.curSec.key.Section,
			Subsection:    p.curSec.key.Subsection,
			HasSubsection: p.curSec.key.HasSubsection,
			Name:          name,
		},
		lineStart: lineStart,
		nameEnd:   p.pos,
		alone:     alone,
	}

	p.skipBlank()

	if p.pos < len(p.data) && p.data[p.pos] == '=' {
		p.pos++
		p.skipBlank()

		o.valueStart = p.pos

		value, err := p.parseValue()
		if err != nil {
			return err
		}

		o.value = value
	} else {
		o.valueless = true
		o.valueStart = o.nameEnd

		// Only a comment may follow a bare variable name. Anything else is
		// a malformed line, which git rejects rather than guessing at.
		if !p.atLineEnd() && p.data[p.pos] != '#' && p.data[p.pos] != ';' {
			return p.err()
		}
	}

	p.skipToLineEnd()

	o.logicalEnd = p.pos
	if p.pos < len(p.data) && p.data[p.pos] == '\r' {
		// git replaces the CR along with the value, so a rewritten line ends
		// up with a bare LF even in a CRLF file.
		o.logicalEnd++
	}

	p.consumeLineEnd()
	o.lineEnd = p.pos

	o.secIdx = len(p.f.sections) - 1
	p.f.options = append(p.f.options, o)
	p.curSec.entryEnd = p.pos

	return nil
}

// parseValue reads a variable's value, honouring quoted runs, backslash
// escapes and backslash-newline continuations, and trimming unquoted trailing
// whitespace.
func (p *parser) parseValue() (string, error) { //nolint:gocognit // parser state machine
	var (
		b        strings.Builder
		inQuote  bool
		lastKeep int
	)

	for p.pos < len(p.data) {
		c := p.data[p.pos]
		if c == 0 {
			return "", p.err()
		}

		switch {
		case c == '\n' || (c == '\r' && p.peekIsLF()):
			if inQuote {
				return "", p.err()
			}

			return b.String()[:lastKeep], nil

		case c == '"':
			inQuote = !inQuote
			}

			if perr.Line != tc.wantLine {
				t.Fatalf("Parse(%q) reported line %d, want %d", tc.src, perr.Line, tc.wantLine)
			}
		})
	}
}

func TestMutationsPreserveFormatting(t *testing.T) {
	t.Parallel()

	const src = `# a comment worth keeping
[user]
	; and an inline note
	name = Old Name
	email = a@b.c

[remote "origin"]
	url = https://x/y.git
[foo]
	bar = one
	bar = two
`

	tests := []struct {
		name string
		do   func(*testing.T, *config.File)
		want string
	}{
		{
			name: "set rewrites only the value",
			do: func(t *testing.T, f *config.File) {
				t.Helper()

				if err := f.Set(mustKey(t, keyUserName), "New Name"); err != nil {
					t.Fatal(err)
				}
			},
			want: strings.Replace(src, "name = Old Name", "name = New Name", 1),
		},
		{
			name: "set on a subsection targets the subsection",
			do: func(t *testing.T, f *config.File) {
				t.Helper()

				if err := f.Set(mustKey(t, keyOriginURL), "https://new/z.git"); err != nil {
					t.Fatal(err)
				}
			},
			want: strings.Replace(src, "url = https://x/y.git", "url = https://new/z.git", 1),
		},
		{
			name: "add appends after the section's last variable",
			do: func(t *testing.T, f *config.File) {
				t.Helper()

				if err := f.Add(mustKey(t, keyUserName), "Second"); err != nil {
					t.Fatal(err)
				}
			},
			want: strings.Replace(src, "\temail = a@b.c\n", "\temail = a@b.c\n\tname = Second\n", 1),
		},
		{
			name: "a new section is appended at end of file",
			do: func(t *testing.T, f *config.File) {
				t.Helper()

				if err := f.Set(mustKey(t, "new.key"), "v"); err != nil {
					t.Fatal(err)
				}
			},
			want: src + "[new]\n\tkey = v\n",
		},
		{
			name: "unset removes the line and nothing else",
			do: func(t *testing.T, f *config.File) {
				t.Helper()

				if _, err := f.UnsetAll(mustKey(t, keyUserName)); err != nil {
					t.Fatal(err)
				}
			},
			want: strings.Replace(src, "\tname = Old Name\n", "", 1),
		},
		{
			name: "unset --all removes every occurrence and the empty section",
			do: func(t *testing.T, f *config.File) {
				t.Helper()

				if _, err := f.UnsetAll(mustKey(t, "foo.bar")); err != nil {
					t.Fatal(err)
				}
			},
			want: strings.Replace(src, "[foo]\n\tbar = one\n\tbar = two\n", "", 1),
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			f := mustParse(t, src)
			tc.do(t, f)

			if got := string(f.Bytes()); got != tc.want {
				t.Fatalf("result mismatch\n--- got ---\n%s\n--- want ---\n%s", got, tc.want)
			}
		})
	}
}

func TestSetRefusesMultipleValues(t *testing.T) {
	t.Parallel()

	f := mustParse(t, "[foo]\n\tbar = one\n\tbar = two\n")

	err := f.Set(mustKey(t, "foo.bar"), "three")
	if !errors.Is(err, config.ErrMultipleValues) {
		t.Fatalf("Set on a multivalued key = %v, want ErrMultipleValues", err)
	}

	if got := string(f.Bytes()); got != "[foo]\n\tbar = one\n\tbar = two\n" {
		t.Fatalf("refused Set modified the file:\n%s", got)
	}

	if err := f.ReplaceAll(mustKey(t, "foo.bar"), "three"); err != nil {
		t.Fatalf("ReplaceAll: %v", err)
	}

	if got, want := string(f.Bytes()), "[foo]\n\tbar = three\n"; got != want {
		t.Fatalf("ReplaceAll = %q, want %q", got, want)
	}
}

func TestReplaceAllUsesLastRepeatedSection(t *testing.T) {
	t.Parallel()

	f := mustParse(t, "[a]\n\tv = one\n[a]\n\tv = two\n")
	if err := f.ReplaceAll(mustKey(t, "a.v"), "three"); err != nil {
		t.Fatal(err)
	}

	if got, want := string(f.Bytes()), "[a]\n[a]\n\tv = three\n"; got != want {
		t.Fatalf("ReplaceAll = %q, want %q", got, want)
